"use client"

/**
 * Clean-room verify-email card.
 * Resend follows the otp-field cooldown: the control stays disabled while the
 * clock runs. The result copy does not say whether an account exists.
 */

import { useEffect, useState } from "react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { verifyCopy, type AuthLocale } from "./auth-recovery-copy"
import { AuthRecoveryFrame, AuthRecoveryLink, type AuthBrand } from "./auth-recovery-frame"
import { OtpField, type OtpFieldState } from "@/components/ui/otp-field"

export type VerifyEmailPhase = "idle" | "invalid" | "submitting" | "success" | "error" | "cooldown"

export type VerifyEmailLabels = Partial<ReturnType<typeof verifyCopy>>

export type VerifyEmailOtp = boolean | { length?: number }

export type VerifyEmailProps = {
  email?: string
  onResend: () => Promise<void>
  onVerifyCode?: (code: string) => Promise<boolean>
  onVerified?: () => void
  onSkip?: () => void
  skipHref?: string
  otp?: VerifyEmailOtp
  labels?: VerifyEmailLabels
  locale?: AuthLocale
  brand?: AuthBrand
  cooldownSeconds?: number
  /** Seconds already elapsed on the cooldown when the card opens. */
  initialCooldown?: number
  phase?: VerifyEmailPhase
  className?: string
}

function formatClock(total: number) {
  const minutes = Math.floor(total / 60)
  const seconds = total % 60
  return `${minutes}:${seconds.toString().padStart(2, "0")}`
}

export function VerifyEmail({
  email,
  onResend,
  onVerifyCode,
  onVerified,
  onSkip,
  skipHref,
  otp,
  labels,
  locale = "en",
  brand,
  cooldownSeconds = 30,
  initialCooldown = 0,
  phase,
  className,
}: VerifyEmailProps) {
  const copy = { ...verifyCopy(locale), ...labels }
  const length = typeof otp === "object" && otp.length ? otp.length : 6
  const showCode = otp !== false && (otp != null || onVerifyCode != null)
  const [internal, setInternal] = useState<VerifyEmailPhase>(initialCooldown > 0 ? "cooldown" : "idle")
  const [remaining, setRemaining] = useState(phase === "cooldown" ? cooldownSeconds : initialCooldown)
  const [busy, setBusy] = useState(false)
  const [code, setCode] = useState("")
  const [otpState, setOtpState] = useState<OtpFieldState>("idle")
  const [server, setServer] = useState(false)
  const current = phase ?? internal
  const success = current === "success"
  const submitting = current === "submitting" || busy
  const clock = formatClock(remaining)
  const waiting = remaining > 0
  const resendName = waiting ? `${copy.resendWait} ${clock}` : submitting ? copy.sending : copy.resend

  useEffect(() => {
    if (remaining <= 0) return
    const timer = window.setTimeout(() => setRemaining((seconds) => Math.max(0, seconds - 1)), 1000)
    return () => window.clearTimeout(timer)
  }, [remaining])

  async function resend() {
    if (waiting || submitting || success || phase === "submitting") return
    setBusy(true)
    setServer(false)
    setInternal("submitting")
    try {
      await onResend()
      setRemaining(cooldownSeconds)
      setCode("")
      setOtpState("idle")
      setInternal("cooldown")
    } catch {
      setServer(true)
      setInternal("error")
    } finally {
      setBusy(false)
    }
  }

  async function verify(next: string) {
    if (!onVerifyCode || submitting || next.length < length) return
    setBusy(true)
    setServer(false)
    setOtpState("idle")
    try {
      const ok = await onVerifyCode(next)
      if (ok) {
        setOtpState("success")
        setInternal("success")
        onVerified?.()
        return
      }
      setCode("")
      setOtpState("error")
      setInternal("invalid")
    } catch {
      setServer(true)
      setInternal("error")
    } finally {
      setBusy(false)
    }
  }

  const showServer = server || current === "error"

  return (
    <AuthRecoveryFrame
      slot="verify-email"
      phase={current}
      title={success ? copy.successTitle : copy.title}
      description={success ? copy.successBody : copy.description}
      status={waiting ? resendName : success ? copy.successBody : ""}
      brand={brand}
      className={className}
    >
      {success ? null : (
        <div className="grid min-w-0 gap-4">
          {email ? (
            <p className="text-sm text-muted-foreground">
              {copy.address} <span className="font-medium break-all text-foreground">{email}</span>
            </p>
          ) : null}
          {showCode ? (
            <form
              className="grid gap-4"
              onSubmit={(event) => {
                event.preventDefault()
                void verify(code)
              }}
              noValidate
            >
              <OtpField
                length={length}
                label={copy.code}
                hint={copy.codeHint}
                errorLabel={copy.codeInvalid}
                successLabel={copy.codeValid}
                value={code}
                onValueChange={(next) => {
                  setCode(next)
                  if (otpState === "error" && next) setOtpState("idle")
                }}
                onComplete={(next) => void verify(next)}
                state={current === "invalid" ? "error" : otpState}
                disabled={submitting}
              />
              <Button type="submit" className="min-h-11 w-full" disabled={submitting} aria-busy={submitting || undefined}>
                {submitting ? copy.checking : copy.verify}
              </Button>
            </form>
          ) : null}
          {showServer ? (
            <p role="alert" className="text-sm text-destructive">
              {copy.serverError}
            </p>
          ) : null}
          <Button
            type="button"
            variant="outline"
            className={cn("min-h-11 w-full", waiting && "font-normal")}
            disabled={waiting || submitting || success}
            aria-disabled={waiting || undefined}
            onClick={() => void resend()}
          >
            {resendName}
          </Button>
          {skipHref ? (
            <AuthRecoveryLink href={skipHref}>{copy.skip}</AuthRecoveryLink>
          ) : onSkip ? (
            <Button type="button" variant="ghost" className="min-h-11 w-full" onClick={onSkip}>
              {copy.skip}
            </Button>
          ) : null}
        </div>
      )}
    </AuthRecoveryFrame>
  )
}

"use client"

/** Clean-room chrome for the recovery cards. No theme of its own. */

import { useEffect, useId, useRef, type ReactNode } from "react"
import { motion, useReducedMotionConfig } from "motion/react"

import { Card } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type AuthBrand = { name: string; mark?: ReactNode }

export function AuthRecoveryLink({ href, children }: { href: string; children: ReactNode }) {
  return (
    <a
      href={href}
      className="inline-flex min-h-11 items-center self-start text-sm font-medium text-foreground underline-offset-4 hover:underline focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
    >
      {children}
    </a>
  )
}

export function AuthRecoveryFrame({
  slot,
  title,
  description,
  status,
  brand,
  phase,
  className,
  children,
}: {
  slot: string
  title: string
  description?: string
  status?: string
  brand?: AuthBrand
  phase: string
  className?: string
  children: ReactNode
}) {
  const reduce = useReducedMotionConfig() ?? false
  const titleId = useId()
  const headingRef = useRef<HTMLHeadingElement>(null)
  const focusTitle = phase === "sent" || phase === "success" || phase === "invalid-link" || phase === "expired"

  useEffect(() => {
    if (focusTitle) headingRef.current?.focus()
  }, [focusTitle, phase, title])

  return (
    <Card
      data-slot={slot}
      data-phase={phase}
      data-motion={reduce ? "reduced" : "full"}
      role="region"
      aria-labelledby={titleId}
      className={cn("@container w-full min-w-0 max-w-md gap-0 overflow-hidden py-0", className)}
    >
      <div className="grid min-w-0 gap-5 p-6 @max-[380px]:p-5">
        {brand ? (
          <p className="inline-flex min-w-0 items-center gap-2 text-sm font-medium">
            {brand.mark ? <span aria-hidden="true">{brand.mark}</span> : null}
            <span className="truncate">{brand.name}</span>
          </p>
        ) : null}
        <motion.div
          key={phase}
          className="grid min-w-0 gap-5"
          initial={reduce ? { opacity: 0 } : { opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: reduce ? 0 : motionPresets.duration.standard, ease: [...motionPresets.ease.enter] }}
        >
          <div className="grid gap-1">
            <h2 id={titleId} ref={headingRef} tabIndex={-1} className="text-xl font-medium text-balance outline-none @min-[380px]:text-2xl">
              {title}
            </h2>
            {description ? <p className="text-sm text-pretty text-muted-foreground">{description}</p> : null}
          </div>
          {children}
        </motion.div>
      </div>
      <p className="sr-only" role="status">
        {status}
      </p>
    </Card>
  )
}

"use client"

import * as React from "react"
import { Check, RotateCcw } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { InputOTP, InputOTPGroup, InputOTPSlot } from "@/components/ui/input-otp"

export type OtpFieldState = "idle" | "success" | "error"

export type OtpFieldProps = {
  length?: number
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  onComplete?: (value: string) => void
  state?: OtpFieldState
  label?: string
  hint?: string
  errorLabel?: string
  successLabel?: string
  resendLabel?: string
  resendWaitLabel?: string
  /** Seconds the resend control stays disabled after each send. */
  cooldownSeconds?: number
  onResend?: () => void
  disabled?: boolean
  autoFocus?: boolean
  inputMode?: "numeric" | "text"
  className?: string
}

function formatClock(total: number) {
  const minutes = Math.floor(total / 60)
  const seconds = total % 60
  return `${minutes}:${seconds.toString().padStart(2, "0")}`
}

export function OtpField({
  length = 6,
  value,
  defaultValue = "",
  onValueChange,
  onComplete,
  state = "idle",
  label = "Verification code",
  hint,
  errorLabel = "That code is not valid",
  successLabel = "Code confirmed",
  resendLabel = "Resend code",
  resendWaitLabel = "Resend in",
  cooldownSeconds = 30,
  onResend,
  disabled = false,
  autoFocus = false,
  inputMode = "numeric",
  className,
}: OtpFieldProps) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue)
  const [remaining, setRemaining] = React.useState(0)
  const groupRef = React.useRef<HTMLDivElement>(null)
  const code = value ?? uncontrolled
  const describedBy = React.useId()

  React.useEffect(() => {
    if (remaining <= 0) return
    const id = window.setTimeout(() => setRemaining((current) => current - 1), 1000)
    return () => window.clearTimeout(id)
  }, [remaining])

  React.useEffect(() => {
    const node = groupRef.current
    if (!node || state === "idle") return
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    if (typeof node.animate !== "function") return
    if (state === "error") {
      node.animate(
        [
          { transform: "translateX(0)" },
          { transform: "translateX(-5px)" },
          { transform: "translateX(5px)" },
          { transform: "translateX(-3px)" },
          { transform: "translateX(0)" },
        ],
        { duration: 420, easing: "ease-in-out" },
      )
    } else {
      node.animate(
        [{ transform: "scale(1)" }, { transform: "scale(1.03)" }, { transform: "scale(1)" }],
        { duration: 320, easing: "ease-out" },
      )
    }
  }, [state])

  function change(next: string) {
    if (value === undefined) setUncontrolled(next)
    onValueChange?.(next)
  }

  return (
    <div data-slot="otp-field" data-state={state} className={cn("flex flex-col gap-2", className)}>
      <span className="text-sm font-medium" id={`${describedBy}-label`}>
        {label}
      </span>
      <div ref={groupRef} className="w-fit">
        <InputOTP
          maxLength={length}
          value={code}
          onChange={change}
          onComplete={onComplete}
          disabled={disabled || state === "success"}
          autoFocus={autoFocus}
          inputMode={inputMode}
          aria-labelledby={`${describedBy}-label`}
          aria-describedby={describedBy}
          aria-invalid={state === "error" || undefined}
          containerClassName={cn(state === "success" && "rounded-lg ring-2 ring-primary")}
        >
          <InputOTPGroup>
            {Array.from({ length }, (_, index) => (
              <InputOTPSlot key={index} index={index} aria-invalid={state === "error" || undefined} />
            ))}
          </InputOTPGroup>
        </InputOTP>
      </div>
      <div className="flex items-center justify-between gap-3">
        <p
          id={describedBy}
          role={state === "error" ? "alert" : "status"}
          className={cn(
            "text-xs text-muted-foreground",
            state === "error" && "text-destructive",
            state === "success" && "text-primary",
          )}
        >
          {state === "error" ? errorLabel : state === "success" ? (
            <span className="inline-flex items-center gap-1">
              <Check className="size-3" aria-hidden />
              {successLabel}
            </span>
          ) : (
            hint
          )}
        </p>
        {onResend ? (
          <Button
            type="button"
            variant="ghost"
            size="xs"
            disabled={disabled || remaining > 0 || state === "success"}
            onClick={() => {
              onResend()
              setRemaining(cooldownSeconds)
            }}
          >
            <RotateCcw />
            {remaining > 0 ? `${resendWaitLabel} ${formatClock(remaining)}` : resendLabel}
          </Button>
        ) : null}
      </div>
    </div>
  )
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    // Exit decelerates, the same curve as CSS ease-out.
    exit: [0, 0, 0.58, 1] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
